head.script:
 	scwin.onpageload = function() {

	};

	scwin.onpageunload = function() {

	};

	var i = 0;
	scwin.fn_addTab = function(){
		var tabOpt = { 
				label : "임시화면" + i, 
				closable : true 
		}; 
		var contOpt = { 
			frameMode : "wframe" ,
			src : "processMsgFrame_WindowContainer_WESE-1002_(WSQ-5874)_sub2.xml"
		};

		tabControl1.addTab('tab0' + i, tabOpt, contOpt);
		var idx = tabControl1.getTabCount();
		tabControl1.setSelectedTabIndex(idx-1);
		i++;
	}


	// 버튼 클릭 시 tab 추가(로딩바 설정)
	scwin.trigger2_onclick = function(e) {debugger;
		var ii = tabControl1.getFrame(tabControl1.getSelectedTabIndex()).id;

        WebSquare.layer.showProcessMessage("Tab_test..", {scope:ii}); // 로딩바 생성
        $p.setTimeout(function(){
            scwin.fn_addTab(); // 탭 생성
            WebSquare.layer.hideProcessMessage({scope:ii});
        }, {delay:3000, key:""}); //timeout
    };

	// onbeforetabclose : tab이 close되기 전 발생
	scwin.tabControl1_onbeforetabclose = function(tabID,idx) {
		tabControl1.getWindow(idx).$w.clearPage(); //원하는 객체가 포함된 scope에 접근하여, 브라우저 초기화
	};
